let pal, BG, CBG;
let NUM_STRIPES = 100;
const DLT_LNS = 4;

function setup() {
	createCanvas(windowWidth, windowHeight);
	frameRate(30);
	noFill();
	stroke("silver");

	NUM_STRIPES = sqrt(width);

	seed = ~~random(987654321); // 329330205
	console.log(`seed: ${seed}`);
	noiseSeed(seed);
	randomSeed(seed);

	pal = [...random(palettes)];   // random palette
	BG = mixLimit(pal, 24); // mix palette and limit highest value to 24 = darken
	if (!CBG) CBG = BG; // very first start, for lerping between different background colors

	loop();
}

function draw() {
	colorMode(RGB);
	CBG = 212; // lerpColor(CBG, BG, 0.05);
  background(CBG); // color(8, 8, 16)

	const num = 1;
