		var clr = random(pal);
		drawStripe(x, -50, height*1.5, random(10, 100), clr, random()<0.5); // skip ~~(random()*random()*3)
	}

	// noLoop() removed for animation
}

function mousePressed() {
	if (mouseButton === RIGHT || (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < width*0.1) return;
	setup();
}

function drawStripe(x, ys, ye, w, clr, skipOdds = false) {
	const nf = 321;

	const clrBri = adjColorBrightness(clr, 1.3);
	const clrDrk = adjColorBrightness(clr, 0.7);
	// clr = 32;
	stroke(clr);

	let lx, ly, lh; // last x, y, height
	const frClr = 32;
	let dir = Math.sign(random()-0.5);
	for (let y = ys, i = 0; y <= ye; y++, i++) {
		const n = noise(x/nf, y/nf, frameCount/nf);
		const h = map(n, 0, 1, 0.2, 0.8) * height / 3;
		if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) line(x - w/2, y, x + w/2, y);

		if (lx && ly && lh && (!skipOdds || i%2)) {
			// outer
			stroke(frClr);  strokeWeight(2)
			if (!skipOdds) noStroke();
			fill(CBG);
			beginShape();
			vertex(lx - w/2, ly);
			vertex(lx + w/2, ly);
			vertex(x + w/2, y);
			vertex(x - w/2, y);
			endShape(CLOSE);

			if (!skipOdds) {
				stroke(frClr)
				line(lx - w/2, ly, x - w/2, y);
				line(lx + w/2, ly, x + w/2, y);
			}

			// shade depending on direction
			stroke(clrDrk);
			if (x < lx) stroke(clrBri)
			stroke(clr); strokeWeight(1);
			// stroke(adjColorBrightness(clr, map(x-lx, -w, w, 0.5, 2)));

			// lines in the stripe, see DLT_LNS

			if (x < lx) {
				// vertical
				const DLT = w/Math.round(w/DLT_LNS);
				const d = DLT/w; // DLT_LNS/w; //  * (x > lx ? 0.5 : 1);
				const m = d; // d
				const y1 = ly; // lerp(ly, y, m);
				const y2 = y; //lerp(ly, y, 1-m);
				for (let f = m; f <= 1.0001 - m; f += d) {
					const x1 = lerp(lx - w/2, lx + w/2, f)
					const x2 = lerp(x - w/2, x + w/2, f)
					const xx = lerp(lx, x, f);
					// marginLine(x1, ly, x2, y, 5);
					marginLine(x1, y1, x2, y2, 2)
					// line(xx-w/2+DLT, y1, xx+w/2-DLT, y2)
				}
			} else {
				// horizontal
				const hh = y - ly;
				var DLT = hh/Math.round(hh/DLT_LNS);
				var d = DLT/hh;
				for (let f = d; f <= 1.0001 - d; f += d) {
					const yy = lerp(ly, y, f)
					var xx = lerp(lx, x, f);
					line(xx - w/2 + DLT, yy, xx +w/2 - DLT, yy);
				}
			}
		}

		lx = x;
		ly = y;
		lh = h;

		if (random() < 0.8) dir *= -1; // high probability to change direction (left/right)
		x += random(0.2, 0.8) * w * dir; // Math.sign(random()-0.5); // noise(y/nf, x/nf, frameCount/nf) * width * 0.3;
		y += random(0.8, 2) * w; // (noise(frameCount/nf, y/nf, x/nf) - 0.5) * height * 0.21;
	}

}

function marginLine(x1, y1, x2, y2, mar = 0) {
	const vec = createVector(x2-x1, y2-y1);
	const len = vec.mag();
	vec.normalize().mult(mar);
	line(x1+vec.x, y1+vec.y, x2-vec.x, y2-vec.y);
}
